create temporary view newitem_candidate_${grass_region_without_quote} as
select
    item_id
    ,shop_id
    ,level1_global_be_category
    ,grass_region
    ,grass_date
    ,create_datetime
    ,substr(create_datetime, 1, 10) as create_date
    ,datediff(${local_date}, date(substr(create_datetime, 1, 10))) as create_diff_days
from mp_item.dim_item__reg_s0_live
where
    tz_type = 'local'
    and grass_date = ${local_date}
    and grass_region  = ${grass_region}
    and status = 1
    and cast(substr(create_datetime, 1, 10) as date) between date_add(${local_date}, -89) and ${local_date}
;

--sql_divide_splitter--
create temporary view ads_active_item_${grass_region_without_quote} as
select
    item_id
    ,max(ads_id) as ads_id
from paimon.mp_paidads.dim_active_item__reg_s0_live
where
    grass_region in (${grass_region})
    and placement in (40, 50) -- ROI2投放
group by item_id
;

--sql_divide_splitter--
insert overwrite table ${schema}.ads_sr_data_warehouse_tc_ni_newitem_90d_pool_di
partition (grass_region = ${grass_region}, local_date = ${local_date})
select
    T1.item_id
    ,T1.shop_id
    ,case
        when T2.ads_id is not null then 'ads'
        else 'org'
    end as ads_type
    ,T1.create_date
    ,T1.create_datetime
    ,T1.create_diff_days
    ,T1.level1_global_be_category
from
    newitem_candidate_${grass_region_without_quote} T1
    left join ads_active_item_${grass_region_without_quote} T2 on T1.item_id = T2.item_id
;
